/** The record, its pinned native tree, the templates, both projectiles and the looping clip clocks. */
export function crossroadsNative(r,n){
 const spec=SPECS[r?.prefabKey];
 if(!spec||r.key!==r.prefabKey||r.level!==0||r.applyWay!=="RANGED"||r.stats.rangeRadius!==0||r.stats.bat!==0.6||r.stats.blockCnt!==1||r.notCountInTotal
  ||r.stats.dmgType!=="arts"||r.stats.motion!=="WALK"||Object.entries(spec.stats).some(([k,v])=>r.stats[k]!==v)
  ||!same(r.abilities,CROSSROADS_ABILITIES)||!same(r.talents,TALENTS)||!same(r.skills,[]))return false;
 if(!same(closure(n),spec.components)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&["Move","Idle"].every(k=>clock.durations[k]===CLOCK.durations[k]&&same(clock.events[k]?.filter(x=>x.name==="OnAttack").map(x=>x.time),CLOCK.events[k]));
}
/** Runtime parameters from the talent, the pinned components and the loops. */
export const crossroadsParams=r=>({interval:1,maxWait:3,
 close:{radius:f32(.7),scale:r.talents.bb["AttackTrigger.attack@CloseAttack"]},
 laser:{speed:6,life:f32(.2),radius:f32(.2),scale:r.talents.bb["AttackTrigger.attack@FourDirAttack"]},
 loops:{Move:{dur:CLOCK.durations.Move,events:CLOCK.events.Move},Idle:{dur:CLOCK.durations.Idle,events:CLOCK.events.Idle}}});
export const CROSSROADS_FEATURES={
 "talent:AttackTrigger":{matchesRecord:isCrossroads,covers:crossroadsNative,ability:{kind:"crossroads",params:crossroadsParams},nativeClaim:()=>({active:5}),
  explains:text=>CROSSROADS_ABILITIES.some(x=>x.text===text),
  stageMultipliers:{"AttackTrigger.attack@FourDirAttack":v=>Number.isFinite(v)&&v>=0,"AttackTrigger.attack@CloseAttack":v=>Number.isFinite(v)&&v>=0},
  note:"1 s close Arts hit plus four cardinal lasers; debris pushing inert without Planetary Debris"},
};
